    31      #[derive(Default)]
    32      pub(crate) struct ExprOrderAcc {
    33          acc: ObservableOrders,
    34
    35
    36          saw_mixed_inputs: bool,
    37
    38          num_ordered_inputs: usize,
    39          last_ordered_node: Option<Node>,
    40      }
    41
    42      impl ExprOrderAcc {
    43          pub(crate) fn add(&mut self, right: ObservableOrders, right_node: Node) {
    44              use ObservableOrders as O;
    45
    46              self.saw_mixed_inputs |= (self.acc.contains(O::INDEPENDENT) && !right.is_empty())
    47                  || (right.contains(O::INDEPENDENT) && !self.acc.is_empty());
    48
    49              if !right.is_empty() {
    50                  self.num_ordered_inputs += 1;
    51                  self.last_ordered_node = Some(right_node);
    52              }
    53
    54              self.acc |= right;
    55          }
    56
    57          pub(crate) fn accumulated_orders(&self) -> ObservableOrders {
    58              self.acc
    59          }
    60
    61          pub(crate) fn saw_mixed_inputs(&self) -> bool {
    62              self.saw_mixed_inputs
    63          }
    64
    65          pub(super) fn single_ordered_node(&self) -> Option<Node> {
    66              (self.num_ordered_inputs == 1).then(|| self.last_ordered_node.unwrap())
    67          }
    68      }
    69  }
