    89  pub(crate) struct ExprOrderSimplifier<'a> {
    90      struct_field_ordering: Option<ObservableOrders>,
    91
    92      revisit_cache: &'a mut PlIndexMap<Node, ObservableOrders>,
    93      internally_observed: ObservableOrders,
    94
    95      expr_arena: &'a mut Arena<AExpr>,
    96  }
    97
    98  impl<'a> ExprOrderSimplifier<'a> {
    99      pub fn new(
   100          expr_arena: &'a mut Arena<AExpr>,
   101          revisit_cache: &'a mut PlIndexMap<Node, ObservableOrders>,
   102      ) -> Self {
   103          Self {
   104              struct_field_ordering: None,
   105
   106              revisit_cache,
   107              internally_observed: ObservableOrders::empty(),
   108
   109              expr_arena,
   110          }
   111      }
   112  }
