   114  impl ExprOrderSimplifier<'_> {
   115      pub fn simplify_projected_exprs(
   116          &mut self,
   117          ae_nodes: &[Node],
   118          allow_deordering_top: bool,
   119      ) -> ObservableOrders {
   120          let mut acc = ExprOrderAcc::default();
   121
   122          for node in ae_nodes.iter().copied() {
   123              acc.add(self.rec(node, RecursionState::NO_DEORDER), node)
   124          }
   125
   126          let acc_observable = acc.accumulated_orders();
   127
   128          if acc.saw_mixed_inputs() {
   129              self.internal_observe(acc_observable);
   130          }
   131
   132          if let Some(node) = acc.single_ordered_node()
   133              && allow_deordering_top
   134          {
   135              self.rec(node, RecursionState::ALLOW_DEORDER)
   136          } else {
   137              acc_observable
   138          }
   139      }
   140
   141      pub fn internally_observed_orders(&self) -> ObservableOrders {
   142          self.internally_observed
   143      }
   144
   145      fn internal_observe(&mut self, observable_orders: ObservableOrders) {
   146          self.internally_observed |= observable_orders;
   147      }
   148
   149      #[recursive::recursive]
   150      fn rec(&mut self, current_ae_node: Node, recursion: RecursionState) -> ObservableOrders {
   151          use ObservableOrders as O;
   152          use RecursionState as RS;
   153
   154          macro_rules! check_return_cached {
   155              () => {
   156                  if let Some(o) = self.revisit_cache.get(&current_ae_node) {
   157                      return *o;
   158                  }
   159              };
   160          }
   161
   162          macro_rules! cache_output {
   163              ($o:expr) => {
   164                  let existing = self.revisit_cache.insert(current_ae_node, $o);
   165                  debug_assert!(existing.is_none());
   166              };
   167          }
   168
   169          if let Some(new_ae) = drop_scalar_order_keys(current_ae_node, self.expr_arena) {
   170              self.expr_arena.replace(current_ae_node, new_ae);
   171              return self.rec(current_ae_node, recursion);
   172          }
   173
   174          match self.expr_arena.get_mut(current_ae_node) {
   175              AExpr::Column(_) => O::COLUMN,
   176
   177              AExpr::Literal(lv) => {
   178                  if lv.is_scalar() {
   179                      O::empty()
   180                  } else {
   181                      O::INDEPENDENT
   182                  }
   183              },
   184
   185              AExpr::Eval {
   186                  expr,
   187                  evaluation,
   188                  variant,
   189              } => {
   190                  check_return_cached!();
   191
   192                  let expr = *expr;
   193                  let evaluation = *evaluation;
   194                  let variant = *variant;
   195
   196                  let mut expr_ordering = self.rec(expr, RS::NO_DEORDER);
   197
   198                  match variant {
   199                      EvalVariant::Array { as_list: _ }
   200                      | EvalVariant::ArrayAgg
   201                      | EvalVariant::List
   202                      | EvalVariant::ListAgg => {},
   203                      EvalVariant::Cumulative { min_samples: _ } => {
   204                          self.internal_observe(expr_ordering);
   205                          expr_ordering |= O::INDEPENDENT;
   206                      },
   207                  };
   208
   209                  self.rec(evaluation, RS::NO_DEORDER);
   210
   211                  cache_output!(expr_ordering);
   212
   213                  expr_ordering
   214              },
   215              AExpr::Element => O::INDEPENDENT,
   216
   217              #[cfg(feature = "dtype-struct")]
   218              AExpr::StructEval {
   219                  expr, evaluation, ..
   220              } => {
   221                  check_return_cached!();
   222
   223                  let evaluation_len = evaluation.len();
   224
   225                  let struct_expr = *expr;
   226                  let struct_field_ordering = self.rec(struct_expr, RS::NO_DEORDER);
   227
   228                  let prev_struct_field_ordering =
   229                      self.struct_field_ordering.replace(struct_field_ordering);
   230
   231                  let mut acc = ExprOrderAcc::default();
   232                  acc.add(struct_field_ordering, struct_expr);
   233
   234                  for i in 0..evaluation_len {
   235                      let AExpr::StructEval { evaluation, .. } = self.expr_arena.get(current_ae_node)
   236                      else {
   237                          unreachable!()
   238                      };
   239
   240                      let node = evaluation[i].node();
   241                      acc.add(self.rec(node, RS::NO_DEORDER), node);
   242                  }
   243
   244                  let mut output_observable = acc.accumulated_orders();
   245                  let mut should_cache = false;
   246
   247                  if acc.saw_mixed_inputs() {
   248                      self.internal_observe(output_observable);
   249                      should_cache = true;
   250                  } else if let Some(node) = acc.single_ordered_node()
   251                      && recursion.allows_deorder()
   252                  {
   253                      output_observable = self.rec(node, RS::ALLOW_DEORDER);
   254                      should_cache = true;
   255                  }
   256
   257                  self.struct_field_ordering = prev_struct_field_ordering;
   258
   259                  if should_cache {
   260                      cache_output!(output_observable);
   261                  }
   262
   263                  output_observable
   264              },
   265
   266              #[cfg(feature = "dtype-struct")]
   267              AExpr::StructField(_) => self.struct_field_ordering.unwrap(),
   268
   269              AExpr::BinaryExpr { .. } | AExpr::Ternary { .. } => {
   270                  check_return_cached!();
   271
   272                  let (nodes, ternary_mask_node) = match self.expr_arena.get(current_ae_node) {
   273                      AExpr::BinaryExpr { left, op: _, right } => ([*left, *right], None),
   274                      AExpr::Ternary {
   275                          predicate,
   276                          truthy,
   277                          falsy,
   278                      } => ([*truthy, *falsy], Some(*predicate)),
   279                      _ => unreachable!(),
   280                  };
   281
   282                  let mut acc = ExprOrderAcc::default();
   283
   284                  for node in nodes {
   285                      acc.add(self.rec(node, RS::NO_DEORDER), node);
   286                  }
   287
   288                  let mut output_observable = acc.accumulated_orders();
   289
   290                  if let Some(ternary_mask_node) = ternary_mask_node {
   291                      acc.add(
   292                          self.rec(ternary_mask_node, RS::NO_DEORDER),
   293                          ternary_mask_node,
   294                      );
   295                  }
   296
   297                  let mut should_cache = false;
   298
   299                  if acc.saw_mixed_inputs() {
   300                      self.internal_observe(output_observable);
   301                      should_cache = true;
   302                  } else if let Some(node) = acc.single_ordered_node()
   303                      && recursion.allows_deorder()
   304                  {
   305                      output_observable = self.rec(node, RS::ALLOW_DEORDER);
   306
   307                      if Some(node) == ternary_mask_node {
   308                          output_observable = O::empty();
   309                      }
   310
   311                      should_cache = true;
   312                  }
   313
   314                  if should_cache {
   315                      cache_output!(output_observable);
   316                  }
   317
   318                  output_observable
   319              },
   320
   321              AExpr::Cast { expr, .. } => {
   322                  let expr = *expr;
   323                  self.rec(expr, recursion)
   324              },
   325              AExpr::Explode { expr, .. } => {
   326                  let expr = *expr;
   327                  let observable_in_input = self.rec(expr, recursion);
   328
   329                  observable_in_input | O::INDEPENDENT
   330              },
   331              AExpr::Len => O::empty(),
   332              AExpr::Sort { expr, options } => {
   333                  let expr = *expr;
   334                  debug_assert!(!options.maintain_order);
   335                  let maintain_order = false;
   336
   337                  if recursion.allows_deorder() {
   338                      self.expr_arena
   339                          .replace(current_ae_node, self.expr_arena.get(expr).clone());
   340
   341                      return self.rec(current_ae_node, recursion);
   342                  }
   343
   344                  let mut out = self.rec(
   345                      expr,
   346                      RecursionState {
   347                          allow_deorder: !maintain_order,
   348                      },
   349                  );
   350
   351                  if maintain_order {
   352                      out |= O::INDEPENDENT;
   353                  } else {
   354                      out = O::INDEPENDENT;
   355                  }
   356
   357                  out
   358              },
   359
   360              AExpr::Filter { input, by } => {
   361                  check_return_cached!();
   362
   363                  let input = *input;
   364                  let by = *by;
   365
   366                  let observable_in_input = self.rec(input, RS::NO_DEORDER);
   367                  let observable_in_by = self.rec(by, RS::NO_DEORDER);
   368
   369                  let mut acc = ExprOrderAcc::default();
   370                  acc.add(observable_in_input, input);
   371                  acc.add(observable_in_by, by);
   372
   373                  if acc.saw_mixed_inputs() {
   374                      self.internal_observe(acc.accumulated_orders());
   375                  } else if observable_in_input.is_empty() && !observable_in_by.is_empty() {
   376                      self.rec(by, RS::ALLOW_DEORDER);
   377                  }
   378
   379                  cache_output!(observable_in_input);
   380
   381                  observable_in_input
   382              },
   383
   384              AExpr::Gather {
   385                  expr,
   386                  idx,
   387                  returns_scalar,
   388                  null_on_oob: _,
   389              } => {
   390                  let expr = *expr;
   391                  let idx = *idx;
   392                  let returns_scalar = *returns_scalar;
   393
   394                  check_return_cached!();
   395
   396                  let observable_in_expr = self.rec(expr, RS::NO_DEORDER);
   397                  let observable_in_idx = self.rec(idx, RS::NO_DEORDER);
   398
   399                  self.internal_observe(observable_in_expr);
   400
   401                  let output_observable = if returns_scalar || observable_in_expr.is_empty() {
   402                      O::empty()
   403                  } else {
   404                      observable_in_idx
   405                  };
   406
   407                  cache_output!(output_observable);
   408
   409                  output_observable
   410              },
   411
   412              AExpr::Over { .. } => {
   413                  check_return_cached!();
   414
   415                  if is_order_insensitive_window(current_ae_node, self.expr_arena) {
   416                      cache_output!(O::COLUMN);
   417                      return O::COLUMN;
   418                  }
   419
   420                  let AExpr::Over {
